using System.Globalization;
using System.Reflection;
using System.Text;

namespace MMLib.Alvo.Analyzers.Generator;

/// <summary>Text pieces every generated file shares: the header, the <c>GeneratedCode</c> attribute, C# literals and XML-safe text.</summary>
internal static class GeneratedText
{
    internal const string Tool = "MMLib.Alvo.Analyzers";

    internal const string Data = "global::MMLib.Alvo.Data.";

    internal static string Version { get; } = InformationalVersion();

    internal static string GeneratedCode => $"[global::System.CodeDom.Compiler.GeneratedCode(\"{Tool}\", \"{Version}\")]";

    internal static void Header(SourceWriter writer, DescriptorModel model) => writer
        .Line("// <auto-generated/>")
        .Line($"// Generated by {Tool} from project '{OneLine(model.Project)}'. Edits are lost on rebuild.")
        .Line("#nullable enable")
        .Line()
        .Line($"namespace {model.Namespace};");

    /// <summary><paramref name="value"/> as a C# string literal.</summary>
    internal static string Literal(string value)
    {
        var builder = new StringBuilder("\"");
        foreach (var c in value)
        {
            builder.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                _ when c < ' ' || c is '\u0085' or '\u2028' or '\u2029' => "\\u" + ((int)c).ToString("x4", CultureInfo.InvariantCulture),
                _ => c.ToString(),
            });
        }

        return builder.Append('"').ToString();
    }

    /// <summary><paramref name="value"/> safe inside an XML documentation comment, on one line.</summary>
    internal static string Xml(string value) =>
        OneLine(value).Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");

    private static string OneLine(string value)
    {
        var builder = new StringBuilder(value.Length);
        foreach (var c in value)
        {
            builder.Append(char.IsControl(c) || c is '\u2028' or '\u2029' ? ' ' : c);
        }

        return builder.ToString();
    }

    private static string InformationalVersion()
    {
        var version = typeof(GeneratedText).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? "0.0.0";
        var metadata = version.IndexOf('+');

        return metadata < 0 ? version : version.Substring(0, metadata);
    }
}
